cat > /tmp/test_custom_eq.py <<'EOF'
import inspect
from rich.repr import auto

class CustomEq:
    def __eq__(self, other):
        return True

class TestClass:
    def __init__(self, a=CustomEq()):
        self.a = a

# Use the decorator
TestClass = auto(TestClass)

def test_custom_eq_repr():
    obj = TestClass()
    # The __rich_repr__ is now attached to the class
    result = list(obj.__rich_repr__())

    # Expected: [('a', <CustomEq object>, <CustomEq object>)]
    # Buggy: [<CustomEq object>]
    assert len(result) == 1
    assert isinstance(result[0], tuple)
    assert result[0][0] == 'a'

if __name__ == "__main__":
    try:
        test_custom_eq_repr()
        print("Test passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")
EOF
timeout 30 python3 /tmp/test_custom_eq.py

